mapper.select:
select id, poi_id, type, image_path, year, description, upload_user_id, review_status, reject_reason,
review_time, reviewer_id, create_time, update_time
from media


        and poi_id = #{poiId}


        and type = #{type}


        and review_status = #{reviewStatus}


        and year >= #{yearFrom}


        and year <= #{yearTo}


order by poi_id asc, year asc, id asc

